CREATE TABLE users (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  phone VARCHAR(20) NOT NULL,
  name VARCHAR(40) NOT NULL DEFAULT '',
  deleted_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00' COMMENT '70 年表示未删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_phone_alive (phone, deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

UPDATE users SET deleted_at = NOW() WHERE id = 1;
SELECT id, phone FROM users WHERE deleted_at = '1970-01-01 00:00:00';
